insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('88710dd6-feae-402d-8c55-fd06b300e28d', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'What Is Architectural Theory?', 'This opening section frames theory as a disciplined way of asking what architecture is, what it does, who it serves, and how it can be judged. Students learn that theory is not an ornament added to design; it is a set of tools for seeing assumptions.', 0),
  ('9fd2253b-fd9a-4a68-9975-b2b2a4c3a7aa', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '88710dd6-feae-402d-8c55-fd06b300e28d', 'subtopic'::public.curated_course_node_type, 'Theory as Question and Method', 'Students define theory as a way of formulating questions, concepts, and arguments about buildings and cities.', 0),
  ('bd0e020e-a025-4b4d-afdc-8790ab4a45e4', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '9fd2253b-fd9a-4a68-9975-b2b2a4c3a7aa', 'concept'::public.curated_course_node_type, 'Concepts, claims, evidence, and critique', null, 0),
  ('a0ffbf9c-2dd8-4e12-a1ea-dd37fa73c862', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '9fd2253b-fd9a-4a68-9975-b2b2a4c3a7aa', 'concept'::public.curated_course_node_type, 'Theory versus history, criticism, and design method', null, 1),
  ('12409c26-7529-40f5-9d56-c9c7a5063c15', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '9fd2253b-fd9a-4a68-9975-b2b2a4c3a7aa', 'concept'::public.curated_course_node_type, 'Normative, descriptive, speculative, and political theory', null, 2),
  ('e67d1255-ec23-43f1-b7fc-8d395b94401b', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '9fd2253b-fd9a-4a68-9975-b2b2a4c3a7aa', 'concept'::public.curated_course_node_type, 'How theory changes what designers notice', null, 3),
