  ('d526575d-1678-49ab-b870-6c282f293bd6', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '3da0181e-4de3-4df9-a8d2-9136d166c47a', 'concept'::public.curated_course_node_type, 'Practice, pedagogy, publication, and public debate', null, 3),
  ('e49e429a-86f9-4ed6-852d-15748e15387b', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '88710dd6-feae-402d-8c55-fd06b300e28d', 'subtopic'::public.curated_course_node_type, 'Reading Buildings and Texts Together', 'Students learn to move between written theory and spatial evidence without reducing one to the other.', 2),
  ('c2273ea5-b076-443c-a9bf-17c84624f493', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'e49e429a-86f9-4ed6-852d-15748e15387b', 'concept'::public.curated_course_node_type, 'Close reading of texts', null, 0),
  ('baece6f6-37de-41e9-b1f1-cf46276853d3', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'e49e429a-86f9-4ed6-852d-15748e15387b', 'concept'::public.curated_course_node_type, 'Formal, spatial, material, and urban analysis', null, 1),
  ('c715b985-335b-42e0-9b16-d8196f699bc9', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'e49e429a-86f9-4ed6-852d-15748e15387b', 'concept'::public.curated_course_node_type, 'Manifestoes, treatises, criticism, and interviews', null, 2),
  ('f3381c17-3f39-4a7e-b453-0870276c81f8', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'e49e429a-86f9-4ed6-852d-15748e15387b', 'concept'::public.curated_course_node_type, 'Using theory to frame a design position', null, 3),
  ('6a67a339-8eb4-4cfa-8df1-dd926d52799f', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Vitruvius, Classical Theory, and the Origins of Architectural Discourse', 'This section introduces classical architectural theory as a durable source of vocabulary, hierarchy, proportion, and professional identity. The point is not to revere the canon, but to understand how architectural authority was constructed.', 1),
  ('a495b883-851d-4179-b73a-979751177347', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a67a339-8eb4-4cfa-8df1-dd926d52799f', 'subtopic'::public.curated_course_node_type, 'Vitruvian Categories and Professional Identity', 'Students examine how Vitruvius linked architecture to knowledge, ethics, public life, and the body.', 0),
  ('7fcffe97-7c43-4ac8-bc49-1082e040022d', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a495b883-851d-4179-b73a-979751177347', 'concept'::public.curated_course_node_type, 'Firmitas, utilitas, venustas', null, 0),
  ('57dc28a0-3f56-4447-af93-0af1a01c44cb', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a495b883-851d-4179-b73a-979751177347', 'concept'::public.curated_course_node_type, 'The architect''s education and breadth of knowledge', null, 1),
  ('7620ac19-ec49-4aeb-af27-cac6b34faf73', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a495b883-851d-4179-b73a-979751177347', 'concept'::public.curated_course_node_type, 'Commodity, firmness, delight, and later translations', null, 2),
  ('d39d4689-3352-43fa-97ab-0cde7da8320d', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a495b883-851d-4179-b73a-979751177347', 'concept'::public.curated_course_node_type, 'Patronage, public works, and civic responsibility', null, 3),
  ('3b5bcbb0-186f-4e09-93c3-75dcb49622b9', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a67a339-8eb4-4cfa-8df1-dd926d52799f', 'subtopic'::public.curated_course_node_type, 'Orders, Proportion, and the Body', 'Classical theory makes proportion and the body central to architectural judgment.', 1),
  ('53b2d7c0-8c0f-4cc5-8eb3-4b17ae654ac2', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '3b5bcbb0-186f-4e09-93c3-75dcb49622b9', 'concept'::public.curated_course_node_type, 'Column orders and decorum', null, 0),
