  ('6931a211-d887-42f1-ae83-4613532de9ad', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '3b5bcbb0-186f-4e09-93c3-75dcb49622b9', 'concept'::public.curated_course_node_type, 'Temple, house, theater, and city as theoretical objects', null, 2),
  ('13689302-53b1-4d5d-9da9-692c4798e4f2', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '3b5bcbb0-186f-4e09-93c3-75dcb49622b9', 'concept'::public.curated_course_node_type, 'Gendered and political assumptions in classical proportion', null, 3),
  ('28e67f9f-88e5-461a-b817-35c166a942b2', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a67a339-8eb4-4cfa-8df1-dd926d52799f', 'subtopic'::public.curated_course_node_type, 'Classical Theory''s Afterlives', 'Students track how classical ideas return in Renaissance, Enlightenment, Beaux-Arts, modern, and postmodern discourse.', 2),
  ('a020c26e-4350-431f-b5f0-209e035b9c5e', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '28e67f9f-88e5-461a-b817-35c166a942b2', 'concept'::public.curated_course_node_type, 'Canon formation and pedagogy', null, 0),
  ('0e248f20-aba5-4273-9c79-92c6cd9b54c8', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '28e67f9f-88e5-461a-b817-35c166a942b2', 'concept'::public.curated_course_node_type, 'Classicism as universal language and political symbol', null, 1),
  ('aec805c5-72df-4c6c-b145-4171709bc01a', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '28e67f9f-88e5-461a-b817-35c166a942b2', 'concept'::public.curated_course_node_type, 'Colonial and state uses of classical imagery', null, 2),
  ('ffeccf3a-414e-427f-8663-63b7f62524ec', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '28e67f9f-88e5-461a-b817-35c166a942b2', 'concept'::public.curated_course_node_type, 'Critique, parody, and reinterpretation', null, 3),
  ('dfea18ea-b467-4c84-a275-ec201c90e2f7', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Renaissance Humanism: Alberti, Palladio, Proportion, and Treatises', 'This unit studies the Renaissance as a moment when architectural theory became textual, authorial, humanist, and print-based. Students learn how theory shaped design practice, professional identity, and historical revival.', 2),
  ('6a2830e5-7bdd-4ac4-8096-13916c5b223b', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'dfea18ea-b467-4c84-a275-ec201c90e2f7', 'subtopic'::public.curated_course_node_type, 'Alberti and Architecture as Liberal Art', 'Students study Alberti''s claim that architecture belongs to intellectual culture, not only building craft.', 0),
  ('277bfaac-d867-4c30-80cc-4fcada5ada19', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a2830e5-7bdd-4ac4-8096-13916c5b223b', 'concept'::public.curated_course_node_type, 'Lineamenta and design as mental work', null, 0),
  ('f56cf93b-5b51-462a-a696-572af055ccb7', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a2830e5-7bdd-4ac4-8096-13916c5b223b', 'concept'::public.curated_course_node_type, 'Beauty, concinnitas, and proportion', null, 1),
  ('25cb268b-c35c-4209-a1b2-7668b38a06ab', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a2830e5-7bdd-4ac4-8096-13916c5b223b', 'concept'::public.curated_course_node_type, 'Patronage, city, and civic order', null, 2),
  ('4fe33f31-f0bb-4731-bd85-4648927b895a', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '6a2830e5-7bdd-4ac4-8096-13916c5b223b', 'concept'::public.curated_course_node_type, 'Theory as professional elevation', null, 3),
  ('a5435129-7a9a-46e5-8b1b-6688a43b2bf7', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'dfea18ea-b467-4c84-a275-ec201c90e2f7', 'subtopic'::public.curated_course_node_type, 'Palladio, Typology, and the Treatise', 'Palladio shows how drawings, measurements, precedents, and books circulate architectural knowledge.', 1),
  ('c6723d12-a4e9-49e0-a9f6-b128f84606d2', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a5435129-7a9a-46e5-8b1b-6688a43b2bf7', 'concept'::public.curated_course_node_type, 'Villa, palace, church, and bridge types', null, 0);
