  ('bae05267-1a34-4fbc-9dce-11278452e809', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Enlightenment Theory: Taste, Sublime, Reason, Type, and Publics', 'This section explores theory as public argument about taste, reason, sensation, morality, institutions, and historical knowledge. Students see architecture as part of Enlightenment debates about society.', 3),
