  ('48c1c8c9-d5b2-49de-aaab-b11356bd6de0', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Modernity, Industrialization, and the Birth of the Manifesto', 'This unit links architectural theory to the social and technological shocks of industrial modernity. Students learn why the manifesto became a privileged modern form of architectural argument.', 4),
