  ('d5de2ea3-f5c5-431e-9619-7a7702169108', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '8aa3ba66-5c7c-4c21-8eac-ffc0bdaa0fc5', 'concept'::public.curated_course_node_type, 'Engineering and architecture as rival authorities', null, 1),
  ('0a2a36e3-aa42-4b19-b6a9-5d38609b1e62', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '8aa3ba66-5c7c-4c21-8eac-ffc0bdaa0fc5', 'concept'::public.curated_course_node_type, 'Expositions and display culture', null, 2),
