  ('8af4176d-31c3-4e7a-b846-e18fc33544df', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '48c1c8c9-d5b2-49de-aaab-b11356bd6de0', 'subtopic'::public.curated_course_node_type, 'Media and the Modern Architectural Public', 'Journals, photographs, exhibitions, and books made modern architecture a discursive movement.', 2),
  ('a87cb670-7661-4ef8-8977-ab666a48fcd8', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '8af4176d-31c3-4e7a-b846-e18fc33544df', 'concept'::public.curated_course_node_type, 'Photography and canon formation', null, 0),
