insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('d7e2ee16-08da-4418-a547-fb50e8e7c407', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Modernist Theory: Function, Form, Social Reform, and the Avant-Garde', 'This section studies modernist theory as multiple, conflicted, and political. Students compare functionalism, social reform, abstraction, standardization, and technological optimism.', 5),
  ('f96311b5-dc67-487c-9802-22b1a67d114e', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'd7e2ee16-08da-4418-a547-fb50e8e7c407', 'subtopic'::public.curated_course_node_type, 'Functionalism and the New Objectivity', 'Students examine claims that architecture should express use, structure, economy, and social need.', 0),
  ('1cce34f6-6c3b-4860-b5e9-203ece691d29', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'f96311b5-dc67-487c-9802-22b1a67d114e', 'concept'::public.curated_course_node_type, 'Form follows function and its interpretations', null, 0),
