  ('4b8e098b-9f18-41b2-9ea3-4ebb0b789760', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '616dd95e-838a-4ae3-a059-780f4cdb95a6', 'concept'::public.curated_course_node_type, 'CIAM and the functional city', null, 0),
