  ('2d93e176-efbf-4044-bbcf-eee601ecf97b', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '616dd95e-838a-4ae3-a059-780f4cdb95a6', 'concept'::public.curated_course_node_type, 'Collective life and mass housing', null, 2),
  ('c561f447-4967-4b61-af71-77b376ea0191', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '616dd95e-838a-4ae3-a059-780f4cdb95a6', 'concept'::public.curated_course_node_type, 'Utopia, control, and lived experience', null, 3),
  ('a22b88aa-8002-4cba-82d8-6b1bf8010903', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Phenomenology, Embodiment, Atmosphere, and Place', 'Phenomenology shifts theory from visual composition to embodied experience. Students study body, memory, material, atmosphere, and place as central architectural concerns.', 6),
