  ('818c9c7c-46e8-43b7-926d-45194347a7d9', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a4bfa92a-626d-4e7e-a872-63639eac46f2', 'concept'::public.curated_course_node_type, 'Pallasmaa and the critique of ocularcentrism', null, 0),
  ('0f31c141-ce2f-4fbb-bb84-cc33d91f859e', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a4bfa92a-626d-4e7e-a872-63639eac46f2', 'concept'::public.curated_course_node_type, 'Touch, sound, smell, movement, and scale', null, 1),
