  ('27d6dc1e-4f19-4f4a-94b1-e844b19e6e07', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a4bfa92a-626d-4e7e-a872-63639eac46f2', 'concept'::public.curated_course_node_type, 'The body as measure and participant', null, 3),
