  ('dabd3832-8e95-486f-a3d9-621c7fd781c5', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', 'a14ec7a5-a1cc-4c8d-b6ab-d08e3a577c2b', 'concept'::public.curated_course_node_type, 'Plural meaning and cultural difference', null, 0),
