  ('0a77e579-4a9c-4c29-8560-792adcd0f279', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Critical Theory, Marxism, Ideology, and Architectural Production', 'This section connects architecture to social power. Students study how buildings and cities reproduce, resist, or reveal capitalism, ideology, class, labor, institutions, and cultural authority.', 9),
