  ('7ab8be5b-d08e-4fc1-9f28-15d4471ab573', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '04a4bb9e-4a98-4097-9694-872c727aaa05', 'concept'::public.curated_course_node_type, 'Queer space and non-normative publics', null, 2),
  ('b5e44132-17df-45ab-bc09-30d02504095b', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '04a4bb9e-4a98-4097-9694-872c727aaa05', 'concept'::public.curated_course_node_type, 'Bodies, bathrooms, safety, and access', null, 3),
