  ('e2f7eb56-8a98-4e77-acd8-77e1d3fb2ac3', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '5c273502-2c88-4f2e-b02e-aaef4ab9df01', 'concept'::public.curated_course_node_type, 'Colonial planning and administrative architecture', null, 0),
