  ('24f726ec-2f7d-48a8-82a2-87699e9f9b1c', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', '4c058d43-7f07-47b6-bfa7-416ca47376a8', 'subtopic'::public.curated_course_node_type, 'Global Modernisms and Translation', 'This subtopic studies modern architecture as multiple, situated, and contested rather than simply exported.', 1),
