  ('d22ae319-9505-4bc9-86a6-7d44b2c72d07', 'd0e1f2a3-4b5c-4e04-9b34-4f5a6b7c8d44', null, 'topic'::public.curated_course_node_type, 'Urban Theory, Density, Everyday Life, Housing, and Public Space', 'This section connects architectural theory to urban life. Students study streets, housing, infrastructure, public space, density, informality, and everyday use as theoretical problems.', 13),
